      font-size: 0.95rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.5rem);
      line-height: 1.05;
    }

    .hero p {
      margin: 0;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.7;
    }

    .preview-card {
      display: grid;
      gap: 1.25rem;
      padding: 1.25rem;
      background: linear-gradient(180deg, rgba(31, 38, 48, 0.95), rgba(18, 24, 32, 0.98));
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      max-width: 32rem;
    }

    .preview-frame {
      aspect-ratio: 4 / 5;
      overflow: hidden;
      border-radius: calc(var(--radius) - 6px);
      border: 1px solid rgba(240, 246, 252, 0.08);
      background: #0f141b;
    }

    .preview-frame img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
