    .danger {
      background: linear-gradient(180deg, #ff938a, var(--danger-strong));
      color: #fff;
      box-shadow: 0 12px 30px rgba(218, 54, 51, 0.28);
    }

    .trigger:hover,
    .danger:hover {
      transform: translateY(-1px);
      background: linear-gradient(180deg, #ff9f97, #e04844);
    }

    .status {
      min-height: 1.5rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    dialog {
      width: min(100% - 2rem, 30rem);
      padding: 0;
      border: 1px solid var(--border);
      border-radius: 1.5rem;
      background: linear-gradient(180deg, #171d26, #11161d);
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(2, 6, 12, 0.72);
      backdrop-filter: blur(5px);
    }

    .dialog-content {
      display: grid;
      gap: 1rem;
      padding: 1.5rem;
    }

    .dialog-content h2 {
      margin: 0;
      font-size: 1.45rem;
    }

    .dialog-content p {
      margin: 0;
      color: var(--muted);
      line-height: 1.65;
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      justify-content: flex-end;
      margin-top: 0.5rem;
    }

    @media (max-width: 40rem) {
      main {
        padding: 2rem 1rem;
      }

      .meta-row,
      .dialog-actions {
        align-items: stretch;
      }

      .actions,
      .dialog-actions {
        flex-direction: column;
      }

      button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
