</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <div class="page-shell">
      <section class="hero" aria-labelledby="page-title">
        <p class="eyebrow">Image library</p>
        <h1 id="page-title">Preview your saved image</h1>
        <p>
          Review image details before taking action. Deleting removes the image from your
          personal library, but this preview lets you confirm the choice first.
        </p>
      </section>

      <section class="preview-card" aria-labelledby="image-title">
        <div class="preview-frame">
          <img
            src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80"
            alt="Golden sunlight over a mountain ridge reflected in a calm lake"
          >
        </div>

        <div class="meta-row">
          <div class="meta-copy">
            <h2 id="image-title">Sunrise on the lake</h2>
            <p>Captured in Banff National Park &middot; 12.4 MB</p>
          </div>

          <div class="actions">
            <button type="button" class="secondary">Share</button>
            <button type="button" class="trigger" id="open-dialog">Delete image</button>
          </div>
        </div>

        <p class="status" id="status-message" aria-live="polite"></p>
      </section>
    </div>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <form method="dialog" class="dialog-content">
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">
        This will remove <strong>Sunrise on the lake</strong> from your library. You can’t undo this action.
      </p>

      <div class="dialog-actions">
        <button type="submit" class="secondary" value="cancel" id="cancel-dialog">Cancel</button>
        <button type="button" class="danger" id="confirm-delete">Delete image</button>
      </div>
    </form>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const openButton = document.getElementById('open-dialog');
    const cancelButton = document.getElementById('cancel-dialog');
    const confirmButton = document.getElementById('confirm-delete');
    const statusMessage = document.getElementById('status-message');
    const previewCard = document.querySelector('.preview-card');

    openButton.addEventListener('click', () => {
      dialog.showModal();
      confirmButton.focus();
    });

    cancelButton.addEventListener('click', () => {
      dialog.close('cancel');
    });

    confirmButton.addEventListener('click', () => {
      dialog.close('confirm');
      previewCard.setAttribute('aria-hidden', 'true');
      previewCard.hidden = true;
      statusMessage.textContent = 'Image deleted from your library.';
      openButton.focus();
    });

    dialog.addEventListener('close', () => {
      if (dialog.returnValue !== 'confirm') {
        statusMessage.textContent = 'Deletion canceled.';
        openButton.focus();
      }
    });
  </script>
</body>
</html>
