    }

    .page-shell {
      display: grid;
      gap: 2rem;
      align-items: start;
    }

    .hero {
      display: grid;
      gap: 1rem;
      max-width: 42rem;
    }

    .eyebrow {
      margin: 0;
      color: var(--accent);
      font-size: 0.95rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.5rem);
      line-height: 1.05;
    }

    .hero p {
      margin: 0;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.7;
    }

    .preview-card {
      display: grid;
      gap: 1.25rem;
      padding: 1.25rem;
      background: linear-gradient(180deg, rgba(31, 38, 48, 0.95), rgba(18, 24, 32, 0.98));
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      max-width: 32rem;
    }

    .preview-card.is-deleted {
      border-color: #5b6672;
      background: linear-gradient(180deg, rgba(25, 31, 39, 0.96), rgba(13, 17, 23, 0.98));
    }

    .preview-card.is-deleted .preview-frame img {
