      box-shadow: 0 12px 30px rgba(218, 54, 51, 0.28);
    }

    .trigger:hover,
    .danger:hover {
      transform: translateY(-1px);
      background: linear-gradient(180deg, #ff9f97, #e04844);
    }

    .status {
      min-height: 1.5rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    dialog {
      width: min(100% - 2rem, 30rem);
      padding: 0;
      border: 1px solid var(--border);
      border-radius: 1.5rem;
      background: linear-gradient(180deg, #171d26, #11161d);
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(2, 6, 12, 0.72);
      backdrop-filter: blur(5px);
    }

    .dialog-content {
      display: grid;
      gap: 1rem;
      padding: 1.5rem;
    }

    .dialog-content h2 {
      margin: 0;
      font-size: 1.45rem;
    }

    .dialog-content p {
      margin: 0;
      color: var(--muted);
      line-height: 1.65;
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      justify-content: flex-end;
      margin-top: 0.5rem;
    }

    @media (max-width: 40rem) {
      main {
        padding: 2rem 1rem;
      }

      .meta-row,
      .dialog-actions {
        align-items: stretch;
      }

      .actions,
      .dialog-actions {
        flex-direction: column;
      }

      button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      body,
      .preview-card,
      dialog {
        background: Canvas;
        color: CanvasText;
      }

      .preview-card,
      .preview-frame,
      dialog,
      button {
        border-color: ButtonText;
      }

      button {
        background: ButtonFace;
        color: ButtonText;
      }

      dialog::backdrop {
        background: rgba(0, 0, 0, 0.7);
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <div class="page-shell">
      <section class="hero" aria-labelledby="page-title">
        <p class="eyebrow">Image library</p>
        <h1 id="page-title">Preview your saved image</h1>
        <p>
          Review image details before taking action. Deleting removes the image from your
          personal library, but this preview lets you confirm the choice first.
        </p>
      </section>

      <section class="preview-card" aria-labelledby="image-title">
        <div class="preview-frame">
          <img
            src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80"
            alt="Golden sunlight over a mountain ridge reflected in a calm lake"
          >
        </div>

        <div class="meta-row">
          <div class="meta-copy">
            <h2 id="image-title">Sunrise on the lake</h2>
            <p>Captured in Banff National Park &middot; 12.4 MB</p>
          </div>

          <div class="actions">
            <button type="button" class="secondary" id="share-image">Share</button>
            <button type="button" class="trigger" id="open-dialog">Delete image</button>
          </div>
        </div>

        <p class="status" id="image-meta-status">Available in your private library.</p>
        <p class="status" id="status-message" aria-live="polite" tabindex="-1"></p>
      </section>
    </div>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <form method="dialog" class="dialog-content">
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">
        This will remove <strong>Sunrise on the lake</strong> from your library. You can't undo this action.
      </p>

      <div class="dialog-actions">
        <button type="submit" class="secondary" value="cancel" id="cancel-dialog">Cancel</button>
        <button type="button" class="danger" id="confirm-delete">Delete image</button>
      </div>
    </form>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const openButton = document.getElementById('open-dialog');
    const shareButton = document.getElementById('share-image');
    const cancelButton = document.getElementById('cancel-dialog');
    const confirmButton = document.getElementById('confirm-delete');
    const imageMetaStatus = document.getElementById('image-meta-status');
    const statusMessage = document.getElementById('status-message');
    const previewCard = document.querySelector('.preview-card');

    openButton.addEventListener('click', () => {
      statusMessage.textContent = '';
      dialog.showModal();
      confirmButton.focus();
    });

    cancelButton.addEventListener('click', () => {
      dialog.close('cancel');
    });

    confirmButton.addEventListener('click', () => {
      dialog.close('confirm');
      previewCard.classList.add('is-deleted');
      imageMetaStatus.textContent = 'Removed from your library.';
      shareButton.disabled = true;
      openButton.disabled = true;
      openButton.textContent = 'Deleted';
      statusMessage.textContent = 'Image deleted from your library.';
      statusMessage.focus();
    });

    dialog.addEventListener('close', () => {
      if (dialog.returnValue !== 'confirm') {
        statusMessage.textContent = 'Deletion canceled.';
        openButton.focus();
      }
    });
  </script>
</body>
</html>
